sys_script_include.script:
var BaseValidatorUtils_v2 = Class.create();
BaseValidatorUtils_v2.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkDuplicateName: function() {
        var name = this.getParameter("sysparm_base_name");
        if (!name) return "";

        var base = new GlideRecordSecure('x_2060759_base_m_0_bases');
        base.addQuery('name', name.trim());
        base.query();

        return base.hasNext() ? "true" : "false";
    },

    checkDuplicateCityState: function() {
        var city = this.getParameter("sysparm_city");
        var state = this.getParameter("sysparm_state");
        if (!city || !state) return "";

        var base = new GlideRecordSecure("x_2060759_base_m_0_bases");
        base.addQuery("city", city.trim());
        base.addQuery("state", state.trim());
        base.query();

        return base.hasNext() ? "true" : "false";
    },

    checkDuplicateManager: function() {
        var manager = this.getParameter("sysparm_manager");
        if (!manager) return "";

        var base = new GlideRecordSecure("x_2060759_base_m_0_bases");
        base.addQuery("manager", manager);
        base.query();

        return base.hasNext() ? "true" : "false";
    },

    type: 'BaseValidatorUtils_v2'
});
